type createRunRequest struct {
	ScheduledFor *string `json:"scheduled_for"`
	StartedAt    string  `json:"started_at"`
	FinishedAt   string  `json:"finished_at"`
	Outcome      string  `json:"outcome"`
	Error        *string `json:"error"`
}

