	}
	got := make([]key, len(attempts))
	for i, attempt := range attempts {
		got[i] = key{attempt.JobID, attempt.RunID, attempt.Attempt}
	}
	want := []key{
		{"a", "r-a1", 1},
		{"b", "r-b1", 1},
